const items = $input.all();

return items.map(item => {
  const text = item.json.text || '';

  // Extract information from Gemini's response
  const category = text.match(/\*\*Categoria:\*\*\s*(.+)/)?.[1]?.trim();
  const sentiment = text.match(/\*\*Sentimento:\*\*\s*(.+)/)?.[1]?.trim();
  const urgency = text.match(/\*\*Urgência:\*\*\s*(.+)/)?.[1]?.trim();

  const response = text.match(
    /\*\*Sugestão de resposta:\*\*\s*([\s\S]*)/i
  )?.[1]?.trim();

  // Retrieve the original form submission
  const formData = $('On form submission').first().json;

  const customerMessage = Object.values(formData).find(
    value => typeof value === 'string' && value.length > 30
  ) || '';

  return {
    json: {
      date: new Date().toISOString(),
      customer_message: customerMessage,
      category: category,
      sentiment: sentiment,
      urgency: urgency,
      suggested_response: response
    }
  };
});
